package com.primehr.rewardsrecognition.api;
import com.primehr.rewardsrecognition.domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.io.InputStream;import java.time.*;import java.util.*;
public final class RrNominationDtos{private RrNominationDtos(){}
 public record CycleInput(@NotBlank@Size(max=80)String code,@NotBlank@Size(max=200)String title,@Size(max=2000)String description,@NotBlank String policyVersionId,@NotNull LocalDate nominationOpensOn,@NotNull LocalDate nominationClosesOn,@NotNull LocalDate evaluationOpensOn,@NotNull LocalDate evaluationClosesOn,@NotNull LocalDate decisionDueOn,LocalDate confermentOn,Long recordVersion){}
 public record Transition(@NotNull Long recordVersion,@NotBlank@Size(max=1000)String reason){}
 public record CycleResponse(String id,long recordVersion,String code,String title,String description,String policyVersionId,int policyDefinitionVersion,String policyFingerprint,LocalDate nominationOpensOn,LocalDate nominationClosesOn,LocalDate evaluationOpensOn,LocalDate evaluationClosesOn,LocalDate decisionDueOn,LocalDate confermentOn,String status,String openedBy,Instant openedAt,String closedBy,Instant closedAt,String transitionReason){}
 public record SourceInput(@NotNull RrNominationSource.Type type,@NotBlank String sourceId,@PositiveOrZero long sourceVersion,String sourceFingerprint,Instant sourceChangedAt){}
 public record GroupMemberInput(@NotNull@Positive Long employeeId,@Min(1)int displayOrder){}
 public record NominationInput(@NotBlank String cycleId,@NotBlank String categoryVersionId,Long individualEmployeeId,@Size(max=300)String groupName,List<@Valid GroupMemberInput>groupMembers,@Size(max=30)String organizationType,@Positive Long organizationId,@NotBlank@Size(max=8000)String contributionNarrative,@Size(max=8000)String committeeNarrative,@Size(max=4000)String publicationNarrative,List<@Valid SourceInput>sources,Long recordVersion){}
 public record MemberResponse(String id,Long employeeId,String employeeNo,String employeeName,Long appointmentId,Long businessUnitId,String sourceFingerprint,int displayOrder){}
 public record SourceResponse(String id,String type,String sourceId,long sourceVersion,String sourceFingerprint,String sourceLabel,Instant sourceChangedAt,Instant capturedAt){}
 public record EvidenceResponse(String id,long recordVersion,String title,String filename,String mediaType,long byteSize,String checksum,String visibility,String uploadedBy,Instant uploadedAt){}
 public record NominationResponse(String id,long recordVersion,String cycleId,String categoryVersionId,int categoryDefinitionVersion,String categoryFingerprint,String nomineeType,Long nominatorEmployeeId,String nominatorEmployeeNo,String nominatorName,Long nominatorAppointmentId,Long nominatorBusinessUnitId,String nominatorFingerprint,Long individualEmployeeId,String individualEmployeeNo,String individualName,Long individualAppointmentId,Long individualBusinessUnitId,String individualFingerprint,String groupName,String organizationType,Long organizationId,String organizationCode,String organizationName,String organizationFingerprint,String contributionNarrative,String committeeNarrative,String publicationNarrative,String status,int contentRevision,String submittedBy,Instant submittedAt,String submissionFingerprint,String withdrawnBy,Instant withdrawnAt,String withdrawalReason,List<MemberResponse>members,List<SourceResponse>sources,List<EvidenceResponse>evidence){}
 public record EvidenceContent(String filename,String mediaType,long size,InputStream stream){}
}
